package com.careerpilot.modules.careerplan.service;
import com.careerpilot.modules.assessment.entity.*;import com.careerpilot.modules.careerplan.dto.CareerPlanDtos.*;import com.careerpilot.modules.profile.entity.Profile;import com.careerpilot.modules.resume.analysis.entity.ResumeAnalysis;import org.springframework.stereotype.Service;import java.util.*;
@Service public class PlacementReadinessService{public static final String VERSION="placement-readiness-rules-v1";public static final String DISCLAIMER="Placement Readiness is a deterministic preparation indicator. It is not a prediction of hiring or placement probability.";
 public ReadinessResponse calculate(Profile profile,SkillGapResponse gap,Optional<ResumeAnalysis>analysis,Optional<AssessmentAttempt>attempt){List<Raw>raw=new ArrayList<>();raw.add(new Raw("PROFILE","Profile",profile.getProfileCompletionPercentage(),20,"AVAILABLE",profile.getProfileCompletionPercentage()+"% of tracked profile fields are complete."));raw.add(new Raw("CAREER_SKILLS","Career skills",gap.score(),40,"AVAILABLE","Coverage is calculated from the curated taxonomy and saved profile proficiency."));raw.add(analysis.map(v->new Raw("RESUME","Resume ATS",v.getAtsScore(),20,"AVAILABLE","Latest deterministic ATS score for the active resume.")).orElse(new Raw("RESUME","Resume ATS",null,20,"UNAVAILABLE","No deterministic ATS analysis exists for the active resume.")));raw.add(attempt.filter(v->v.getStatus()==AttemptStatus.SUBMITTED&&v.getScorePercentage()!=null).map(v->new Raw("ASSESSMENT","Assessment",v.getScorePercentage(),20,"AVAILABLE","Latest submitted assessment score.")).orElse(new Raw("ASSESSMENT","Assessment",null,20,"UNAVAILABLE","No submitted assessment result is available.")));
  int availableWeight=raw.stream().filter(v->v.score()!=null).mapToInt(Raw::weight).sum();double total=raw.stream().filter(v->v.score()!=null).mapToDouble(v->v.score()*v.weight()).sum();int score=availableWeight==0?0:(int)Math.round(total/availableWeight);List<ReadinessComponent>components=raw.stream().map(v->new ReadinessComponent(v.key(),v.label(),v.score(),v.weight(),v.score()==null?0:(int)Math.round(v.weight()*100d/availableWeight),v.status(),v.evidence())).toList();List<String>improve=new ArrayList<>();if(profile.getProfileCompletionPercentage()<100)improve.add("Complete the missing profile fields.");if(!gap.missingCore().isEmpty())improve.add("Prioritize missing core skills: "+join(gap.missingCore())+".");if(!gap.needsImprovement().isEmpty())improve.add("Strengthen beginner-level core skills: "+join(gap.needsImprovement())+".");if(analysis.isEmpty())improve.add("Upload, parse, and run deterministic analysis on an active resume.");else if(analysis.get().getAtsScore()<70)improve.add("Address truthful issues identified by the deterministic resume analysis.");if(attempt.isEmpty())improve.add("Complete an available assessment to add assessment evidence.");else if(attempt.get().getScorePercentage()!=null&&attempt.get().getScorePercentage()<70)improve.add("Review weak assessment topics and take a fresh attempt when ready.");return new ReadinessResponse(score,VERSION,components,List.copyOf(improve),DISCLAIMER);}
 private String join(List<SkillGapItem>items){return items.stream().map(SkillGapItem::skill).limit(4).reduce((a,b)->a+", "+b).orElse("");}private record Raw(String key,String label,Integer score,int weight,String status,String evidence){}
}

